    <div className="reader" ref={reader} onScroll={e=>{const el=e.currentTarget;bottom.current=el.scrollHeight-el.scrollTop-el.clientHeight<100;if(bottom.current)setUnread(false)}}>{more&&<Button disabled={paging} onClick={older}>{paging?'正在读取…':'加载更早记录'}</Button>}{!shown.length&&<div className="empty"><h2>这一页，等你写下</h2><p>{more?'已加载的记录中还没有这个场景，可继续读取更早记录。':'这里尚未留下故事。可以前往现场，或返回当前场景。'}</p></div>}{shown.map(run=><section className="story-run" key={run.id}>{game.index[run.id]&&<div className="chapter-label">{shortTime(game.index[run.id].time)} · {roomName(game.index[run.id].room)}</div>}{run.messages.map((m:any)=><Message key={m.id} message={m}/>)}{['running','preparing'].includes(run.status)&&<p className="run-status" role="status">{run.phase==='preparing'?'正在准备现场…':run.phase==='extensions'?'正文已写下，正在整理状态…':'故事正在继续…'}</p>}{run.status==='failed'&&<p className="run-status error-text">本轮生成失败，显示已保存的内容。</p>}{run.status==='stopped'&&<p className="run-status">已停止生成。</p>}</section>)}{unread&&<Button onClick={()=>{bottom.current=true;reader.current?.scrollTo({top:reader.current.scrollHeight,behavior:'smooth'});setUnread(false)}}>回到最新内容</Button>}</div>
    <div className="scene-actions">{!game.pending&&runs.at(-1)?.extensions?.actionSuggestions?.status==='ready'&&runs.at(-1).extensions.actionSuggestions.items.map((text:string,i:number)=><Button key={'suggestion-'+i} disabled={disabled} onClick={()=>choose(text)}>{text}</Button>)}{game.pending?<><p>{game.pending.action||'当前有一段事件待继续。'}</p><Button primary disabled={disabled} onClick={()=>send(game.pending.action||'继续当前现场，承接已发生的事情。',game.pending.channel,game.pending.thread)}>继续当前行动</Button></>:<><Button disabled={disabled} onClick={()=>choose('留在'+roomName(game.room)+'，继续眼前的交谈与行动。')}>继续交谈</Button>{routes.slice(0,4).map((a:any)=><Button key={a.route+a.id} disabled={disabled} onClick={()=>a.id==='赴约'?send(a.文案||a.id):execute({type:'route',route:a.route,id:a.id})}>{a.文案||a.名称||a.id}</Button>)}<Button disabled={disabled} onClick={()=>execute({type:'time',mode:'推进一时段'})}>度过一时段</Button></>}</div>
   </>}
   {tab==='手机'&&<div className="page-content"><span className="eyebrow">联络与来信</span><h1>手机</h1><p className="muted">选择联系人查看记录；回复会进入当前会话。</p><div className="contact-tabs">{Object.keys(c.户).map(id=><Button key={id} aria-pressed={thread===id} onClick={()=>setThread(id)}>{R.people[id].妻名}</Button>)}</div><div className="phone-thread">{game.phone.filter((m:any)=>m.thread===thread).map((m:any)=><article className={'bubble '+(m.from==='我'?'mine':'')} key={m.id}><small>{m.from} · {shortTime(m.time)}</small><RichText text={m.text}/></article>)}{!game.phone.some((m:any)=>m.thread===thread)&&<div className="empty"><h2>还没有消息</h2><p>向{R.people[thread]?.妻名}发起联络。</p></div>}</div><div className="action-list"><Button disabled={disabled||!!game.pending} onClick={()=>send('通过手机询问'+R.people[thread]?.妻名+'现在是否方便聊聊。','手机',thread)}>发起联络</Button><Button disabled={disabled||!!game.pending} onClick={preparePhone}>填写回复</Button>{game.pending?.channel==='手机'&&<><Button primary disabled={disabled} onClick={()=>send(game.pending.action,'手机',game.pending.thread)}>继续当前联络</Button><Button disabled={disabled} onClick={()=>execute({type:'cancelContact'})}>取消联络</Button></>}</div></div>}
   {tab==='事务'&&<div className="page-content"><span className="eyebrow">公寓日常</span><h1>把日子安排妥当</h1><div className="segments">{['今日','商店','背包','住户','调查','衣柜','休息'].map(s=><Button key={s} aria-pressed={section===s} onClick={()=>setSection(s)}>{s}</Button>)}</div>
    {section==='今日'&&<>{!c.系统._管理考核.活跃任务.length&&<div className="empty"><h2>眼下没有待办</h2><p>时间前进后，楼里的新消息会来到这里。</p></div>}{c.系统._管理考核.活跃任务.map((t:any)=><article className="task" key={t.id}><div><small>{t.级别} · {roomName(t.地点)}</small><h3>{t.模板}</h3><p>{t.公开摘要||'安排合适的方式处理这件楼务。'}</p></div><div className="action-list">{game.room!==t.地点?<Button disabled={disabled||!!game.pending} onClick={()=>execute({type:'move',room:t.地点})}>前往处理</Button>:R.taskOptions(t).map((o:any)=><Button key={o.id} disabled={disabled||!!game.pending} onClick={()=>execute({type:'task',id:t.id,choice:o.id})}>{o.文案||o.名称||o.id} · {o.消耗}{o.数量}</Button>)}</div></article>)}<div className="quiet-panel"><h3>本期账目</h3><div className="numbers">{['本期实收','本期应上交','本期实际上交'].map(k=><span key={k}>{k}<b>¥{c.系统._管理考核[k]}</b></span>)}</div></div></>}
    {section==='商店'&&<><div className="contact-tabs"><Button aria-pressed={filter==='全部'} onClick={()=>setFilter('全部')}>全部</Button>{shop.map((g:any)=><Button key={g.页签} aria-pressed={filter===g.页签} onClick={()=>setFilter(g.页签)}>{g.页签}</Button>)}</div><div className="shop-list">{shop.filter((g:any)=>filter==='全部'||filter===g.页签).flatMap((g:any)=>g.商品).map((item:any)=><article className="product" key={item.id}><div><small>{item.类别}</small><h3>{item.名称}</h3><p>{item.描述}</p></div><Button title={E.unavailable(item.id)||undefined} disabled={disabled||!!game.pending||c.现金<item.价格||!!E.unavailable(item.id)} onClick={()=>execute({type:'buy',id:item.id})}>{E.unavailable(item.id)?'暂未开放':'¥'+item.价格+' · '+(item.价格?'购买':'领取')}</Button></article>)}</div></>}
    {section==='背包'&&<>{!inventory.length&&<div className="empty"><h2>背包还很轻</h2><p>购入的物品会出现在这里。</p></div>}{inventory.map(id=>{const item=R.items[id];return <article className="product" key={id}><div><small>持有 {c.背包.filter((v:string)=>v===id).length} 件</small><h3>{item?.名称||id}</h3><p>{item?.描述||'剧情中取得的物品。'}</p></div><div className="action-list">{(item?.资源效果||item?.类别==='特殊场景')&&<Button disabled={disabled||!!game.pending} onClick={()=>execute({type:'use',id})}>使用</Button>}{['礼物','服饰'].includes(item?.类别)&&here.map((person:string)=><Button key={person} disabled={disabled||!!game.pending} onClick={()=>execute({type:'gift',id,room:person})}>赠给{R.people[person].妻名}</Button>)}</div></article>})}</>}
    {section==='住户'&&Object.entries(c.户).map(([id,data]:any)=><article className="task" key={id}><div><small>{id} · 月租 ¥{R.people[id].月租||0}</small><h3>{R.people[id].妻名}</h3><p>{data._欠租笔数?`目前欠租 ${data._欠租笔数} 笔`:'账目清楚'}</p></div><div className="action-list"><Button onClick={()=>{setPerson(id);openDrawer('people')}}>人物资料</Button><Button disabled={disabled||!!game.pending} onClick={()=>execute({type:'move',room:id})}>前往</Button>{data._欠租笔数>0&&['硬催','宽限','垫上'].map(mode=><Button disabled={disabled||!!game.pending||game.room!==id} key={mode} onClick={()=>execute({type:'rent',room:id,mode})}>{mode}</Button>)}</div></article>)}
    {section==='调查'&&<><p className="muted">线索藏在不同的日常渠道里。地点、道具与冷却沿用原规则。</p>{Object.keys(c.户).map(id=><article className="task" key={id}><div><small>{id} · 已收集 {c.户[id].妻.裂缝.碎片进度}/4</small><h3>{R.people[id].妻名}</h3><p>{c.户[id].妻.裂缝.已确认?'线索已经读懂。':'从生活痕迹中寻找线索。'}</p></div><div className="action-list">{[['trash','翻找垃圾'],['inquire','向街坊打听'],['drink','邀请对饮'],['installCamera','布设摄像头'],['camera','查看监控'],['readClue','整理线索']].map(([mode,label])=><Button key={mode} disabled={disabled||!!game.pending} onClick={()=>execute({type:'inspect',room:id,mode})}>{label}</Button>)}</div>{game.investigation?.偷窥待选?.门牌===id&&<div className="action-list">{(R.clues(id)?.偷窥?.[game.investigation.偷窥待选.拍]?.选项||[]).map((o:any,i:number)=><Button key={i} disabled={disabled||!!game.pending} onClick={()=>execute({type:'inspect',room:id,mode:'cameraChoice',choice:i})}>{typeof o==='string'?o:JSON.stringify(o)}</Button>)}</div>}<details><summary>社交旧迹</summary>{R.social(id).map((post:any,i:number)=><article className="archive-entry" key={i}><p>{post.文||post.文案||post.内容||post.正文||''}</p>{post.关键?.选项?.map((o:any,j:number)=><Button key={j} disabled={disabled||!!game.pending} onClick={()=>execute({type:'inspect',room:id,mode:'socialInspect',post:i,choice:j})}>{typeof o==='string'?o:JSON.stringify(o)}</Button>)}</article>)}</details></article>)}</>}
