&<p className="empty">尚未形成长期记忆。</p>}{archive==='承诺'&&!Object.keys(game.promises).length&&<p className="empty">眼下没有记录在案的承诺。</p>}{archive==='纪要'&&!game.chronicles.length&&<p className="empty">阶段纪要会随故事积累。</p>}</div>}
  </section><aside className="scene-panel">{stats}</aside></div>
  {drawer&&<div className="drawer-backdrop" onClick={()=>setDrawer('')}><aside className="mobile-panel" role="dialog" aria-modal="true" aria-label={drawer==='rooms'?'地点':'人物状态'} onClick={e=>e.stopPropagation()}><div className="drawer-head"><strong>{drawer==='rooms'?'公寓地点':'现场与人物'}</strong><Button autoFocus onClick={()=>setDrawer('')}>关闭</Button></div>{drawer==='rooms'?nav:stats}</aside></div>}
 </main>
}

